import {createClinic} from './scene.js';
import {speciesInfo,exams,treatments,cases,freshPatient,loadState,availableDiagnosis,quality} from './data.js';
let state=loadState(),scene,toastTimer,modalCleanup=()=>{},audioCtx,audioNodes=[],soundOn=false,petAt=0,examBusy=false;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const current=()=>cases[state.index%cases.length],patient=()=>state.patient;
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('mosslight-save',JSON.stringify(state));$('#save-label').textContent='✓ 进度已自动保存';}catch{$('#save-label').textContent='本次进度暂未保存，请勿关闭页面';}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400);}
function bubble(msg){$('#scene-bubble').textContent=msg;}
function tone(freq=520,duration=.14){if(!soundOn||!audioCtx)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.07,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}
function toggleAudio(){try{if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();soundOn=!soundOn;audioNodes.forEach(n=>{try{n.stop();}catch{}});audioNodes=[];if(soundOn){[130.81,196,261.63,329.63].forEach((f,i)=>{let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=f;g.gain.value=.011/(i+1);o.connect(g);g.connect(audioCtx.destination);o.start();audioNodes.push(o);});tone(660,.4);}$('#sound-button').style.color=soundOn?'#38694f':'#7e897c';$('#sound-button').setAttribute('aria-label',soundOn?'关闭环境音乐':'开启环境音乐');$('#sound-button').title=soundOn?'关闭环境音乐':'开启环境音乐';toast(soundOn?'森林和弦已开启':'声音已关闭');}catch{toast('此浏览器暂不支持环境音乐。');}}
function openModal(html){modalCleanup();modalCleanup=()=>{};$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){modalCleanup();modalCleanup=()=>{};$('#modal').close();}
$('.modal-close').onclick=closeModal;$('#modal').addEventListener('cancel',()=>{modalCleanup();modalCleanup=()=>{};});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function render(){const c=current(),p=patient(),s=speciesInfo[c.species];$('#coins').textContent=state.coins;$('#day-label').textContent=`第 ${state.day} 天 · 森林之春`;$('#patient-name').textContent=c.name;$('#patient-species').textContent=`${s.name} · ${c.age} 岁`;$('#rarity').textContent=s.rarity;$('#personality').textContent=s.personality;$('#patient-story').textContent=c.story;$('#patient-owner').textContent='— '+c.owner;for(let k of ['health','magic','trust']){$('#'+k+'-value').textContent=`${p[k]} / 100`;$('#'+k+'-bar').style.width=p[k]+'%';}if($('.compact-pet'))$('.compact-pet').textContent=`♡ 安抚 ${c.name} · ${p.trust}`;
 $('#queue-count').textContent=String(cases.length-1);$('#queue').innerHTML=[1,2].map(n=>{const q=cases[(state.index+n)%cases.length];return `<div class="queue-item"><span class="creature-thumb ${q.species}"></span><div><b>${q.name}</b><small>${speciesInfo[q.species].name}</small></div><span>候诊中</span></div>`;}).join('');
 $$('.tool-grid button').forEach(b=>{b.classList.toggle('complete',p.exams.includes(b.dataset.exam));b.disabled=examBusy||p.phase!=='observe';});scene?.markExams(p.exams);const step=p.phase==='observe'?0:p.phase==='diagnose'?1:2;$$('#steps>div').forEach((el,i)=>{el.classList.toggle('active',i===step);el.classList.toggle('done',i<step);});
 let html='';if(p.phase==='observe'){html=`<h3 class="case-content-title">发现的小线索 <span>${p.exams.length} / 4</span></h3>`;if(!p.exams.length)html+='<div class="empty-clue"><span>⌕</span>每一种症状，都在悄悄说话。<br>选择下方工具，为小伙伴做检查。</div>';html+=cluesHTML();html+=`<button class="primary diagnose-button" id="diagnose" ${availableDiagnosis(p)&&!examBusy?'':'disabled'}>分析症状 · 作出诊断</button><p class="little-note">${availableDiagnosis(p)?'线索足够了，也可以继续完整检查。':'至少收集 3 条线索后，即可开始诊断。'}</p>`;$('#case-tip').textContent='先安抚，再检查。信任你的动物，会更愿意接受治疗。';}
 else if(p.phase==='diagnose'){html=`<h3 class="case-content-title">你的诊断是什么？ <span>${p.exams.length} 条线索</span></h3>`;html+=c.options.map((x,i)=>`<button class="diagnosis-option" data-diagnosis="${i}">${x}<small>点击选择诊断</small></button>`).join('');html+='<button class="soft-button" id="review-clues" style="width:100%">重新查看检查记录</button>';$('#case-tip').textContent=p.diagnosisMistakes?c.hint:'综合检查结果再做判断。不确定时，可以重新查看线索。';}
 else if(p.phase==='treat'){html=`<span class="success-label">✓ 已确诊 · ${c.diagnosis}</span><h3 class="case-content-title">选择下一步治疗 <span>${p.treated.length} / 2</span></h3><p class="little-note" style="text-align:left;margin:0 0 14px">${c.treatmentHint}</p>`;html+=Object.entries(treatments).map(([id,t])=>`<div class="treatment-item"><span>${t.icon}</span><div><b>${t.name}</b><small>${t.desc}</small></div><button data-treatment="${id}" ${p.treated.includes(id)?'disabled':''}>${p.treated.includes(id)?'完成':'选择'}</button></div>`).join('');$('#case-tip').textContent=p.treated.length?'已经完成第一项治疗，再接再厉。':'选择适合病因的方式，完成两项温柔治疗。';}
 else if(p.phase==='care'){html=`<span class="success-label">✓ 治疗完成</span><h3 class="case-content-title">康复前的小照护</h3><p class="little-note" style="text-align:left;margin-bottom:18px">${c.recovery}</p>`;html+=[['food','❧','喂一点'+s.food,'恢复精神'],['brush','♡','轻轻梳理毛发','建立信任'],['rest','☾','盖好毯子休息','安心恢复']].map(([id,icon,title,desc])=>`<div class="treatment-item"><span>${icon}</span><div><b>${title}</b><small>${desc}</small></div><button data-care="${id}" ${p.care.includes(id)?'disabled':''}>${p.care.includes(id)?'完成':'照护'}</button></div>`).join('');html+=`<button class="primary" id="discharge" ${p.care.length>=2?'':'disabled'} style="margin-top:20px">${p.care.length>=2?'办理康复出院':'完成至少 2 项照护'}</button>`;$('#case-tip').textContent='治愈不止于治疗，安心陪伴也是良药。';}
 else{html=`<div class="modal-icon">❧</div><h3>今天的温柔，收到了。</h3><p class="modal-copy">${c.name}已经健康出院。下一位小伙伴正在等你。</p><button class="primary" id="next-patient">接待下一位病人</button>`;}
 $('#case-content').innerHTML=html;$('#diagnose')?.addEventListener('click',()=>{if(examBusy||!availableDiagnosis(p))return;p.phase='diagnose';render();save();});$$('[data-diagnosis]').forEach(b=>b.onclick=()=>diagnose(c.options[Number(b.dataset.diagnosis)]));$('#review-clues')?.addEventListener('click',()=>{p.phase='observe';render();save();});$$('[data-treatment]').forEach(b=>b.onclick=()=>chooseTreatment(b.dataset.treatment));$$('[data-care]').forEach(b=>b.onclick=()=>care(b.dataset.care));$('#discharge')?.addEventListener('click',discharge);$('#next-patient')?.addEventListener('click',nextPatient);renderDaily();}
function cluesHTML(){const c=current();return patient().exams.map(id=>`<article class="clue"><div class="clue-header"><span>${exams[id].symbol}</span><b>${c.clues[id][0]}</b><span>已记录</span></div><p>${c.clues[id][1]}</p></article>`).join('');}
async function examine(id){const p=patient();if(!exams[id])throw new Error('未知检查工具');if(p.phase!=='observe'){toast('当前检查已完成，请继续右侧诊疗步骤。');return {ok:false,reason:'wrong_phase'};}if(examBusy)return {ok:false,reason:'busy'};if(p.exams.includes(id)){toast(current().clues[id][1]);return {ok:true,alreadyChecked:true};}examBusy=true;render();bubble(`${exams[id].name}中…别怕，很快就好。`);scene?.effect(id==='magic'?'#c8b8ec':'#f5e3ab');tone(520);await new Promise(r=>setTimeout(r,900));p.exams.push(id);p.trust=Math.min(100,p.trust+4+(state.upgrades.includes('lens')?2:0));examBusy=false;checkDaily();render();save();bubble(['谢谢你轻轻地检查。','原来检查一点也不可怕。','嗷呜…我好像更安心了。'][p.exams.length%3]);toast(`已记录：${current().clues[id][0]}`);return {ok:true,clue:current().clues[id]};}
function pet(){if(Date.now()-petAt<1200)return;petAt=Date.now();const p=patient();if(p.trust>=100){bubble('我已经完全信任你啦。');scene?.pet();return;}p.trust=Math.min(100,p.trust+(state.upgrades.includes('blanket')?16:10));scene?.pet();tone(660,.25);bubble(p.trust>=80?'呼噜噜…在这里好安心。':'你的手暖暖的，我没那么害怕了。');checkDaily();render();save();}
function diagnose(choice){const p=patient(),c=current();if(p.phase!=='diagnose'||!availableDiagnosis(p))return {ok:false};if(choice!==c.diagnosis){p.diagnosisMistakes++;tone(230);toast('再想一想：'+c.hint);render();save();return {ok:false,hint:c.hint};}p.phase='treat';tone(740,.3);toast('诊断正确！让我们一起帮助'+c.name+'恢复。');bubble('你找到让我不舒服的原因了吗？');render();save();return {ok:true,diagnosis:c.diagnosis};}
function chooseTreatment(id){const p=patient(),c=current();if(p.phase!=='treat'||$('#modal').open)return;if(id!==c.plan[p.treated.length]){p.treatmentMistakes++;toast('这个步骤暂时帮不上忙。'+c.treatmentHint);save();return;}startMinigame(id);}
function completeTreatment(id){const p=patient();if(p.phase!=='treat'||p.treated.includes(id)||id!==current().plan[p.treated.length])return;p.treated.push(id);p.health=Math.min(100,p.health+22);p.magic=Math.min(100,p.magic+29);p.trust=Math.min(100,p.trust+10);if(p.treated.length===2){p.phase='care';p.health=95;p.magic=92;scene?.heal();bubble(current().recovery);}else{scene?.effect();bubble('舒服多了…谢谢你！');}tone(880,.35);checkDaily();render();save();openModal(`<div class="modal-icon">✓</div><div class="modal-kicker">A LITTLE BETTER</div><h2 class="modal-title">${treatments[id].name}完成</h2><p class="modal-copy">${current().name}舒服地伸了个懒腰。${p.phase==='care'?'治疗完成了，再陪它做一点康复照护吧。':'还有一项治疗，就快恢复啦。'}</p><button class="primary" id="continue-care">继续照顾它</button>`);$('#continue-care').onclick=closeModal;}
function startMinigame(id){const t=treatments[id];if(t.game==='timing')timingGame(id);else if(t.game==='memory')memoryGame(id);else cleanGame(id);}
function miniBase(id,instruction){const t=treatments[id];return `<div class="modal-icon">${t.icon}</div><div class="modal-kicker">GENTLE TREATMENT</div><h2 class="modal-title">${t.name}</h2><p class="modal-copy">${instruction}</p>`;}
function timingGame(id){let hits=0,misses=0,raf,active=true,locked=false,start=performance.now();openModal(miniBase(id,'当指针进入绿色区域时点击。成功 3 次，就能完成这次温柔治疗。')+'<div class="mini-track"><div class="mini-zone"></div><div class="mini-cursor"></div></div><p class="mini-count" id="mini-count">已完成 0 / 3</p><button class="primary" id="timing-hit">轻轻施加</button><button class="soft-button hidden" id="assist" style="width:100%;margin-top:10px">辅助完成</button>');let pos=0;const speed=state.upgrades.includes('crystal')?.0013:.0018;function frame(now){if(!active)return;pos=(Math.sin((now-start)*speed)+1)*50;const el=$('.mini-cursor');if(el)el.style.left=pos+'%';raf=requestAnimationFrame(frame);}raf=requestAnimationFrame(frame);modalCleanup=()=>{active=false;cancelAnimationFrame(raf);};$('#timing-hit').onclick=()=>{if(locked||!active)return;locked=true;setTimeout(()=>locked=false,200);if(pos>=40&&pos<=62){hits++;tone(660+hits*80);$('#mini-count').textContent=`很好，已完成 ${hits} / 3`;if(hits>=3)completeTreatment(id);}else{misses++;$('#mini-count').textContent='轻一点，再等指针进入绿色区域。';if(misses>=2)$('#assist').classList.remove('hidden');}};$('#assist').onclick=()=>completeTreatment(id);}
function memoryGame(id){let seq=[0,2,1],progress=0,misses=0,timers=[],ready=false;const icons=id==='herb'?['❧','✿','✦']:['●','☾','✧'],names=id==='herb'?['星叶','月花','露晶']:['星莓','月饼','光露'];openModal(miniBase(id,id==='herb'?'记住药材亮起的顺序，再依次点击，调配一份温和的星草药水。':'记住点心亮起的顺序，再按顺序喂给它。小口慢慢来。')+`<div class="mini-herbs">${icons.map((v,i)=>`<button class="herb-button" data-herb="${i}" aria-label="${names[i]}" title="${names[i]}">${v}</button>`).join('')}</div><p class="mini-count" id="mini-count">先看一看顺序…</p><button class="primary secondary" id="replay-sequence">再看一次</button><button class="soft-button hidden" id="assist" style="width:100%;margin-top:10px">辅助完成</button>`);
 function playback(){timers.forEach(clearTimeout);$$('.herb-button').forEach(b=>b.classList.remove('flash'));ready=false;progress=0;$('#mini-count').textContent='先看一看顺序…';seq.forEach((v,i)=>{timers.push(setTimeout(()=>{const b=$(`[data-herb="${v}"]`);b?.classList.add('flash');tone(440+v*150);},500+i*750));timers.push(setTimeout(()=>$(`[data-herb="${v}"]`)?.classList.remove('flash'),950+i*750));});timers.push(setTimeout(()=>{ready=true;if($('#mini-count'))$('#mini-count').textContent='轮到你了 · 0 / 3';},2800));}
 $$('.herb-button').forEach(b=>b.onclick=()=>{if(!ready)return;const n=Number(b.dataset.herb);if(n===seq[progress]){progress++;tone(500+progress*100);b.classList.add('flash');timers.push(setTimeout(()=>b.classList.remove('flash'),250));$('#mini-count').textContent=`很好！${progress} / 3`;if(progress===3){ready=false;timers.push(setTimeout(()=>completeTreatment(id),350));}}else{misses++;progress=0;$('#mini-count').textContent='没关系，正确顺序：'+seq.map(i=>names[i]).join(' → ');if(misses>=2)$('#assist').classList.remove('hidden');}});$('#replay-sequence').onclick=playback;$('#assist').onclick=()=>completeTreatment(id);modalCleanup=()=>{ready=false;timers.forEach(clearTimeout);};playback();}
function cleanGame(id){let left=6;openModal(miniBase(id,'轻点每一团灰紫色的异质魔力，把它们变回干净的星光。')+'<div class="clean-orbs" id="clean-orbs"></div><p class="mini-count" id="mini-count">还有 6 团魔力需要净化</p>');[[12,15],[47,9],[75,26],[20,62],[54,68],[78,70]].forEach(([x,y],i)=>{const b=document.createElement('button');b.className='clean-orb';b.setAttribute('aria-label','净化魔力 '+(i+1));b.textContent='✧';b.style.left=x+'%';b.style.top=y+'%';b.onclick=()=>{b.remove();left--;tone(500+(6-left)*90);$('#mini-count').textContent=`还有 ${left} 团魔力需要净化`;if(!left)completeTreatment(id);};$('#clean-orbs').append(b);});}
function care(id){const p=patient();if(p.phase!=='care'||p.care.includes(id))return;p.care.push(id);p.health=Math.min(100,p.health+3);p.magic=Math.min(100,p.magic+4);p.trust=Math.min(100,p.trust+8);scene?.pet();bubble(id==='food'?'吧唧吧唧…这是我最喜欢的味道！':id==='brush'?'呼噜…可以再摸一下吗？':'晚安，温柔的医生。');checkDaily();render();save();}
function discharge(){const p=patient(),c=current();if(p.phase!=='care'||p.care.length<2||p.rewarded)return;const stars=quality(p),bonus=state.upgrades.includes('notebook')?20:0,reward=c.reward+bonus;p.rewarded=true;p.phase='done';p.health=100;p.magic=100;state.coins+=reward;state.healed++;state.history.unshift({name:c.name,species:c.species,diagnosis:c.diagnosis,stars,day:state.day});checkDaily();render();save();scene?.heal();bubble(`${c.name}：我会想你的，医生！`);openModal(`<div class="modal-icon">❧</div><div class="modal-kicker">A HAPPY LITTLE GOODBYE</div><h2 class="modal-title">${c.name}，可以回家啦。</h2><div class="stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><p class="modal-copy">${c.recovery}<br>森林里又多了一个健康快乐的小伙伴。</p><div class="result-stats"><div><b>+${reward}</b><span>诊疗金币</span></div><div><b>${p.trust}</b><span>最终信任</span></div><div><b>${state.healed}</b><span>累计治愈</span></div></div><button class="primary" id="next-in-modal">${state.healed%6===0?'完成巡诊 · 继续新一天':'接待下一位病人'}</button>`);$('#next-in-modal').onclick=()=>{closeModal();nextPatient();};}
function nextPatient(){if(patient().phase!=='done')return;state.index++;if(state.index%3===0){state.day++;state.daily={heal:false,trust:false,exam:false};toast('新的一天，诊所小日常已更新。');}state.patient=freshPatient(state.index);scene?.setSpecies(current().species);scene?.reset();$('#rotate-button').classList.remove('on');$('#page-subtitle').textContent=`正在照顾 ${current().name} · ${speciesInfo[current().species].name}`;bubble(`${current().name}：医生，你好呀…`);render();save();}
function checkDaily(){const p=patient(),goals=[['heal',p.rewarded,60],['trust',p.trust>=80,30],['exam',p.exams.length===4,40]];for(let[id,done,reward]of goals)if(done&&!state.daily[id]){state.daily[id]=true;state.coins+=reward;setTimeout(()=>toast(`小日常完成！获得 ${reward} ✦`),900);}}
function renderDaily(){const n=Object.values(state.daily).filter(Boolean).length;$('#daily-count').textContent=`今日目标 · ${n} / 3`;for(let id of ['heal','trust','exam'])$('#daily-'+id).classList.toggle('done',state.daily[id]);$('#healed-progress').textContent=state.daily.heal?'✓ 已治愈一位病人':'0 / 1 位病人';$('#trust-progress').textContent=state.daily.trust?'✓ 已获得充分信任':`信任达到 80 · 当前 ${patient().trust}`;$('#exam-progress').textContent=state.daily.exam?'✓ 已完成完整检查':`完成 ${patient().exams.length} / 4 项检查`;}
const upgrades=[{id:'blanket',icon:'▰',name:'柔软安抚毯',desc:'一条晒过太阳的小毯子。每次安抚增加 16 点信任。',price:90},{id:'lens',icon:'⌕',name:'星纹魔力透镜',desc:'让检查更轻柔。每次检查额外增加 2 点信任。',price:140},{id:'crystal',icon:'✧',name:'稳态治疗晶石',desc:'让能量流动更平稳。治疗小游戏的指针移动得更慢。',price:180},{id:'notebook',icon:'▤',name:'精装诊疗手账',desc:'细心记录每一次治愈。每次成功出院额外获得 20 枚金币。',price:220}];
function renderPharmacy(){$('#pharmacy-page').innerHTML='<div class="page-intro"><div><h2>把小小诊所，变得更温柔。</h2><p>用治愈奖励添置装备。所有基础治疗都免费提供，每一位奇兽都能得到照顾。</p></div><span>⚗</span></div><div class="cards-grid">'+upgrades.map(u=>`<article class="shop-card"><div class="shop-icon">${u.icon}</div><h3>${u.name}</h3><p>${u.desc}</p><div class="price">✦ ${u.price} 枚森林金币</div><button class="primary ${state.upgrades.includes(u.id)?'secondary':''}" data-buy="${u.id}" ${state.upgrades.includes(u.id)||state.coins<u.price?'disabled':''}>${state.upgrades.includes(u.id)?'✓ 已装备':state.coins<u.price?'金币暂时不足':'购入并装备'}</button></article>`).join('')+'</div><div class="log-list"><h3>随身药材箱</h3><p>星叶、月花、露晶、冰晶与柔云绷带由森林互助协会免费供应。治疗期间，可在诊疗记录中选择对应疗法并亲手操作。</p></div>';$$('[data-buy]').forEach(b=>b.onclick=()=>{const u=upgrades.find(x=>x.id===b.dataset.buy);if(state.upgrades.includes(u.id)||state.coins<u.price)return;state.coins-=u.price;state.upgrades.push(u.id);save();render();renderPharmacy();tone(780);toast(u.name+'已装备！');});}
function renderGuide(){$('#guide-page').innerHTML='<div class="page-intro"><div><h2>认识你的奇幻小伙伴。</h2><p>每一种动物都有自己的习性。用耐心读懂症状，用温柔建立信任。所有病症与治疗均为幻想世界设定。</p></div><span>▤</span></div><div class="guide-grid">'+Object.entries(speciesInfo).map(([id,s])=>`<article class="guide-card"><div class="guide-image ${id}" role="img" aria-label="${s.name}"></div><div class="guide-card-content"><h3>${s.name}</h3><small>${s.latin}</small><p>${s.text}</p><div class="guide-tags">${s.tags.map(t=>'<span>'+t+'</span>').join('')}</div></div></article>`).join('')+'</div><div class="log-list"><h3>我的治愈手账 <span style="color:#9ba78b;font-size:12px">'+state.healed+' 次温柔相遇</span></h3>'+(state.history.length?state.history.slice(0,30).map(h=>`<div class="log-entry"><span>第 ${esc(h.day)} 天 · ${esc(h.name)} / ${speciesInfo[h.species].name}</span><span>${esc(h.diagnosis)} · 康复</span><span style="color:#bba25b">${'★'.repeat(h.stars)}</span></div>`).join(''):'<p>还没有出院记录。完成第一位小伙伴的治疗，就能留下第一段温暖记忆。</p>')+'</div>';}
function navigate(page){if(!['clinic','pharmacy','guide'].includes(page))throw new Error('未知页面');$$('.page-view').forEach(el=>el.classList.toggle('hidden',el.id!==page+'-page'));$$('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#page-title').innerHTML=page==='clinic'?'今天，也要温柔以待。<span class="heading-leaf">✧</span>':page==='pharmacy'?'给每一份照顾，加一点魔法。':'把每次相遇，记在心里。';$('#page-subtitle').textContent=page==='clinic'?`正在照顾 ${current().name} · ${speciesInfo[current().species].name}`:page==='pharmacy'?'诊疗装备与森林药材，让照护更从容。':'奇兽百科与诊疗记录，都在这里。';if(page==='pharmacy')renderPharmacy();if(page==='guide')renderGuide();}
function help(){openModal('<div class="modal-icon">✚</div><div class="modal-kicker">WELCOME TO MOSSLIGHT</div><h2 class="modal-title">欢迎，森林里的新医生。</h2><p class="modal-copy">放慢一点，你的第一位小病人需要你。</p><ol class="help-list"><li>拖动诊疗台旋转视角，滚轮可以缩放。</li><li>使用四种工具收集症状，至少检查三项。</li><li>根据线索选择诊断，再按顺序治疗。</li><li>完成小游戏，给予至少两项康复照护。</li><li>送它回家，领取金币并升级诊所。</li></ol><p class="modal-copy" style="font-size:12px">可以轻轻安抚病人，提升信任。小游戏支持辅助完成，失误不会伤害动物。进度保存在当前浏览器。</p><button class="primary" id="help-close">开始照顾小伙伴</button>');$('#help-close').onclick=closeModal;}
function achievements(){openModal('<div class="modal-icon">♧</div><div class="modal-kicker">SMALL ACTS, BIG HEART</div><h2 class="modal-title">属于你的森林荣誉</h2>'+[['♡','第一份温柔','治愈 1 位奇兽',state.healed>=1],['✧','值得信任的医生','任意病人信任达到 80',state.daily.trust||state.history.length>0],['♧','森林的好朋友','累计治愈 6 位奇兽',state.healed>=6],['▤','奇兽全科医生','照顾全部 4 种奇兽',new Set(state.history.map(h=>h.species)).size>=4],['★','细心的诊疗大师','完成 3 次三星诊疗',state.history.filter(h=>h.stars===3).length>=3]].map(([i,n,d,done])=>`<div class="achievement"><span>${i}</span><div><b>${n}</b><small>${d}</small></div><em>${done?'已获得':'进行中'}</em></div>`).join(''));}
$$('[data-exam]').forEach(b=>b.onclick=()=>examine(b.dataset.exam));$('#pet-button').onclick=pet;$('#sound-button').onclick=toggleAudio;$('#help-button').onclick=help;$('#achievements-button').onclick=achievements;$$('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#rotate-button').onclick=()=>{$('#rotate-button').classList.toggle('on',scene?.rotate());};$('#reset-view').onclick=()=>{scene?.reset();$('#rotate-button').classList.remove('on');};$('#fullscreen-button').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.scene-panel').requestFullscreen();}catch{toast('此浏览器不支持全屏，请使用旋转与缩放查看。');}};$('#daily-heal').onclick=()=>toast(state.daily.heal?'奖励已自动领取，做得真好。':'完成治疗和至少 2 项康复照护，即可出院。');$('#daily-trust').onclick=()=>{navigate('clinic');pet();};$('#daily-exam').onclick=()=>{navigate('clinic');toast('使用四种不同工具，完成完整检查。');};
try{scene=createClinic($('#scene'),examine);scene.setSpecies(current().species);}catch(err){console.error('3D scene unavailable',err);$('#scene-loading').innerHTML='<span class="loading-cross">✚</span><p>此浏览器暂无法开启 3D 场景。<br>请使用支持 WebGL 的浏览器。<br>你仍可使用下方工具继续诊疗。</p>';}
const compact=document.createElement('button');compact.className='compact-pet';compact.setAttribute('aria-label','轻轻安抚当前病人');compact.onclick=pet;$('.scene-top').append(compact);
render();$('#page-subtitle').textContent=`正在照顾 ${current().name} · ${speciesInfo[current().species].name}`;bubble(patient().phase==='done'?'下一位小伙伴正在等你。':current().name+'：今天有一点不舒服…');
const context=document.modelContext;if(context?.registerTool){const lifetime=new AbortController();try{Promise.resolve(context.registerTool({name:'read_clinic_state',title:'查看奇兽诊疗进度',description:'读取当前动物、已经收集的症状、诊疗阶段及诊所金币。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input&&Object.keys(input).length)throw new Error('此工具不接受参数');return {patient:current().name,species:speciesInfo[current().species].name,phase:patient().phase,clues:patient().exams.map(id=>current().clues[id]),coins:state.coins,healed:state.healed};}},{signal:lifetime.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});}catch{}}
